{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "kit_contents_h2",
        "water_food_header_stack",
        "water_text",
        "food_text",
        "baby_food_text",
        "pet_food_text",
        "warmth_shelter_header_stack",
        "blankets_text",
        "clothing_text",
        "matches_text",
        "tent_text",
        "light_power_h3",
        "flashlights_text",
        "headlamps_text",
        "radio_text",
        "power_bank_text",
        "car_charger_text",
        "first_aid_header_stack",
        "first_aid_kit_text",
        "meds_text",
        "whistle_text",
        "multi_tool_text",
        "dust_masks_text",
        "comm_docs_header_stack",
        "mobile_phones_text",
        "documents_text",
        "cash_text",
        "hygiene_h3",
        "toiletries_text",
        "sanitation_text",
        "activities_text",
        "shovel_text",
        "road_salt_text",
        "quick_actions_h2",
        "get_prepared_button",
        "montreal_urgence_button",
        "sources_h2",
        "gov_canada_source",
        "montreal_source"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "72-Hour Winter Storm Preparedness for Montreal",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Preparing an emergency kit is crucial for a family of four to safely navigate a severe winter storm in Montreal for up to 72 hours. This kit focuses on essential supplies for warmth, sustenance, safety, and communication in case of power outages and isolation."
      },
      "children": []
    },
    "kit_contents_h2": {
      "type": "Text",
      "props": {
        "text": "Emergency Kit Contents for a Family of Four",
        "variant": "h2"
      },
      "children": []
    },
    "water_food_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "water_icon",
        "water_food_h3"
      ]
    },
    "water_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000404_01_5_water.svg"
      },
      "children": []
    },
    "water_food_h3": {
      "type": "Text",
      "props": {
        "text": "Water & Food",
        "variant": "h3"
      },
      "children": []
    },
    "water_text": {
      "type": "Text",
      "props": {
        "text": "Water: At least 4 liters per person per day (48 liters total for 4 people, 3 days). Include some for hygiene."
      },
      "children": []
    },
    "food_text": {
      "type": "Text",
      "props": {
        "text": "Non-perishable food: Easy-to-prepare items like canned goods, energy bars, dried fruit, nuts, and comfort foods. Manual can opener needed."
      },
      "children": []
    },
    "baby_food_text": {
      "type": "Text",
      "props": {
        "text": "Baby formula/food: If applicable."
      },
      "children": []
    },
    "pet_food_text": {
      "type": "Text",
      "props": {
        "text": "Pet food: If applicable."
      },
      "children": []
    },
    "warmth_shelter_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "thermometer_icon",
        "warmth_shelter_h3"
      ]
    },
    "thermometer_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000421_01_2_thermometer-half.svg"
      },
      "children": []
    },
    "warmth_shelter_h3": {
      "type": "Text",
      "props": {
        "text": "Warmth & Shelter",
        "variant": "h3"
      },
      "children": []
    },
    "blankets_text": {
      "type": "Text",
      "props": {
        "text": "Warm blankets or sleeping bags: One per person."
      },
      "children": []
    },
    "clothing_text": {
      "type": "Text",
      "props": {
        "text": "Extra layers of warm clothing: Hats, gloves, scarves, thermal underwear, wool socks."
      },
      "children": []
    },
    "matches_text": {
      "type": "Text",
      "props": {
        "text": "Waterproof matches or lighter: For emergency heat (if safe to use) or cooking."
      },
      "children": []
    },
    "tent_text": {
      "type": "Text",
      "props": {
        "text": "Tent or tarp: For emergency shelter or to create a warm zone within the home."
      },
      "children": []
    },
    "light_power_h3": {
      "type": "Text",
      "props": {
        "text": "Light & Power",
        "variant": "h3"
      },
      "children": []
    },
    "flashlights_text": {
      "type": "Text",
      "props": {
        "text": "Flashlights: At least two, with extra batteries."
      },
      "children": []
    },
    "headlamps_text": {
      "type": "Text",
      "props": {
        "text": "Headlamps: Hands-free lighting."
      },
      "children": []
    },
    "radio_text": {
      "type": "Text",
      "props": {
        "text": "Battery-powered or crank radio: With extra batteries."
      },
      "children": []
    },
    "power_bank_text": {
      "type": "Text",
      "props": {
        "text": "Power bank: Fully charged, for mobile devices."
      },
      "children": []
    },
    "car_charger_text": {
      "type": "Text",
      "props": {
        "text": "Car charger: For mobile devices."
      },
      "children": []
    },
    "first_aid_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "bandaid_icon",
        "first_aid_h3"
      ]
    },
    "bandaid_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000402_01_2_bandaid.svg"
      },
      "children": []
    },
    "first_aid_h3": {
      "type": "Text",
      "props": {
        "text": "First Aid & Safety",
        "variant": "h3"
      },
      "children": []
    },
    "first_aid_kit_text": {
      "type": "Text",
      "props": {
        "text": "Comprehensive first-aid kit: Including pain relievers, antiseptic wipes, bandages, gauze, medical tape."
      },
      "children": []
    },
    "meds_text": {
      "type": "Text",
      "props": {
        "text": "Prescription medications: At least a 7-day supply."
      },
      "children": []
    },
    "whistle_text": {
      "type": "Text",
      "props": {
        "text": "Whistle: To signal for help."
      },
      "children": []
    },
    "multi_tool_text": {
      "type": "Text",
      "props": {
        "text": "Multi-tool or utility knife."
      },
      "children": []
    },
    "dust_masks_text": {
      "type": "Text",
      "props": {
        "text": "Dust masks: To filter contaminated air."
      },
      "children": []
    },
    "comm_docs_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "phone_icon",
        "comm_docs_h3"
      ]
    },
    "phone_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000401_01_1_phone.svg"
      },
      "children": []
    },
    "comm_docs_h3": {
      "type": "Text",
      "props": {
        "text": "Communication & Documents",
        "variant": "h3"
      },
      "children": []
    },
    "mobile_phones_text": {
      "type": "Text",
      "props": {
        "text": "Fully charged mobile phones."
      },
      "children": []
    },
    "documents_text": {
      "type": "Text",
      "props": {
        "text": "Important documents: Copies of identification, insurance policies, bank records, stored in a waterproof bag."
      },
      "children": []
    },
    "cash_text": {
      "type": "Text",
      "props": {
        "text": "Cash: Small bills, as ATMs and electronic payments may not work."
      },
      "children": []
    },
    "hygiene_h3": {
      "type": "Text",
      "props": {
        "text": "Hygiene & Other Essentials",
        "variant": "h3"
      },
      "children": []
    },
    "toiletries_text": {
      "type": "Text",
      "props": {
        "text": "Toiletries: Toothbrushes, toothpaste, soap, hand sanitizer."
      },
      "children": []
    },
    "sanitation_text": {
      "type": "Text",
      "props": {
        "text": "Moist towelettes, garbage bags, and plastic ties: For personal sanitation."
      },
      "children": []
    },
    "activities_text": {
      "type": "Text",
      "props": {
        "text": "Books, games, or activities: To keep children occupied."
      },
      "children": []
    },
    "shovel_text": {
      "type": "Text",
      "props": {
        "text": "Shovel: For clearing snow."
      },
      "children": []
    },
    "road_salt_text": {
      "type": "Text",
      "props": {
        "text": "Road salt or sand: For traction on icy surfaces."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "get_prepared_button": {
      "type": "Button",
      "props": {
        "label": "Get Prepared"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.getprepared.gc.ca/cnt/rsrcs/pblctns/yprprdnssgd/index-en.aspx"
          }
        }
      },
      "children": []
    },
    "montreal_urgence_button": {
      "type": "Button",
      "props": {
        "label": "Montreal Urgence"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://montreal.ca/en/topics/emergency-preparedness"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "gov_canada_source": {
      "type": "Text",
      "props": {
        "text": "Government of Canada - Emergency Preparedness Guide"
      },
      "children": []
    },
    "montreal_source": {
      "type": "Text",
      "props": {
        "text": "City of Montreal - Emergency Preparedness"
      },
      "children": []
    }
  }
}
